public class InnerComputeEnvironmentInstanceLaunchTemplateFactory(Action<Humidifier.Batch.ComputeEnvironmentTypes.InstanceLaunchTemplate> factoryAction = null) : SubResourceFactory<Humidifier.Batch.ComputeEnvironmentTypes.InstanceLaunchTemplate>
{

    internal InnerComputeEnvironmentManagedInstancesStorageConfigurationFactory StorageConfigurationFactory { get; set; }

    internal InnerComputeEnvironmentManagedInstancesNetworkConfigurationFactory NetworkConfigurationFactory { get; set; }

    internal InnerComputeEnvironmentInstanceRequirementsFactory InstanceRequirementsFactory { get; set; }

    internal InnerComputeEnvironmentCapacityReservationsFactory CapacityReservationsFactory { get; set; }

    internal InnerComputeEnvironmentManagedInstancesLocalStorageConfigurationFactory LocalStorageConfigurationFactory { get; set; }

    protected override Humidifier.Batch.ComputeEnvironmentTypes.InstanceLaunchTemplate Create()
    {
        var instanceLaunchTemplateResult = CreateInstanceLaunchTemplate();
        factoryAction?.Invoke(instanceLaunchTemplateResult);

        return instanceLaunchTemplateResult;
    }

    private Humidifier.Batch.ComputeEnvironmentTypes.InstanceLaunchTemplate CreateInstanceLaunchTemplate()
    {
        var instanceLaunchTemplateResult = new Humidifier.Batch.ComputeEnvironmentTypes.InstanceLaunchTemplate();

        return instanceLaunchTemplateResult;
    }
    public override void CreateChildren(Humidifier.Batch.ComputeEnvironmentTypes.InstanceLaunchTemplate result)
    {
        base.CreateChildren(result);

        result.StorageConfiguration ??= StorageConfigurationFactory?.Build();
        result.NetworkConfiguration ??= NetworkConfigurationFactory?.Build();
        result.InstanceRequirements ??= InstanceRequirementsFactory?.Build();
        result.CapacityReservations ??= CapacityReservationsFactory?.Build();
        result.LocalStorageConfiguration ??= LocalStorageConfigurationFactory?.Build();
    }

} // End Of Class

